SELECT request_id, from_member_id, to_member_id, apply_message, status,
       deleted_flag, create_time, update_time
FROM t_friend_request
WHERE request_id = #{requestId}
  AND deleted_flag = #{deletedFlag}

SELECT request_id, from_member_id, to_member_id, apply_message, status,
       deleted_flag, create_time, update_time
FROM t_friend_request
WHERE from_member_id = #{fromMemberId}
  AND to_member_id = #{toMemberId}
  AND status = #{status}
  AND deleted_flag = #{deletedFlag}
LIMIT 1

mapper.update:
UPDATE t_friend_request
SET status = #{status}, update_time = #{updateTime}
WHERE request_id = #{requestId}
  AND deleted_flag = 0
  AND status = #{expectStatus}
